import numpy as np
t=df['t'].values; A=df['A'].values; y=df['dA_dt'].values
def nm(cols):
    X=np.column_stack(cols)
    c,_,_,_=np.linalg.lstsq(X,y,rcond=None)
    r=y-X@c
    return np.mean(r**2)/np.var(y)
